package setup

import (
	"fmt"
	"reflect"
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-376: dk setup has no router, so no jobs registry and no blink: a
// verification in flight shows a fixed "●" followed by its text, and nothing
// ticks. The wizard no longer owns a braille spinner.

func hasBraille(s string) bool {
	for _, r := range s {
		if r >= 0x2800 && r <= 0x28FF {
			return true
		}
	}
	return false
}

// firstMsg runs cmd and returns what it yields within a short window. A real
// verification may do I/O (keyring, engine daemon): when nothing comes back in
// time the cmd is not a tick and not a batch, which is all the callers need.
func firstMsg(cmd tea.Cmd) tea.Msg {
	if cmd == nil {
		return nil
	}
	ch := make(chan tea.Msg, 1)
	go func() { ch <- cmd() }()
	select {
	case msg := <-ch:
		return msg
	case <-time.After(1500 * time.Millisecond):
		return nil
	}
}

// requireNoTick fails when cmd is a batch (a verification alone is a single
// Cmd: a second one is the tick) or yields a spinner tick.
func requireNoTick(t *testing.T, what string, cmd tea.Cmd) {
	t.Helper()
	msg := firstMsg(cmd)
	if _, ok := msg.(tea.BatchMsg); ok {
		t.Errorf("%s: Cmd is a batch (%d members), want the verification alone, no tick", what, len(msg.(tea.BatchMsg)))
		return
	}
	if msg != nil && fmt.Sprintf("%T", msg) == "spinner.TickMsg" {
		t.Errorf("%s: Cmd yielded a spinner.TickMsg, want no tick", what)
	}
}

func TestSecretBackendCheckShowsTheFixedDotAndText(t *testing.T) {
	m := New()
	m.width, m.height = 100, 30
	m = past(t, m, "staging")
	if m.secretBackendCheck != secretBackendChecking {
		t.Fatalf("secretBackendCheck = %v, want checking", m.secretBackendCheck)
	}
	out := ansi.Strip(m.Render())
	if !strings.Contains(out, "● Checking whether this is reachable...") {
		t.Errorf("secret backend question lacks %q:\n%s", "● Checking whether this is reachable...", out)
	}
	if hasBraille(out) {
		t.Errorf("render holds a braille glyph:\n%s", out)
	}
}

